    const seed = seedSpec("sentence-lab", passage, { sentenceIndex: 1 });
    const seen: number[] = [];
    const lines = ["They crowd people close.", "They bring people near."].map(
      (value) =>
        JSON.stringify({
          op: "add",
          path: "/elements/tool/props/variants/-",
          value,
